import{_ as i,a0 as a,w as u,s,I as o,x as e,a1 as n,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"不编写代码也可以为开源项目做出贡献 | LCTT x X-CMD","titleTemplate":false,"description":"不编写代码也可以为开源项目做出贡献 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"不编写代码也可以为开源项目做出贡献 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"不编写代码也可以为开源项目做出贡献 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230309.1 ⭐️ Contribute to open source without code","title":"不编写代码也可以为开源项目做出贡献","tag":"202303","desc":""},"relativePath":"202303/20230309.1 ⭐️ Contribute to open source without code.md","filePath":"[post].md"}'),d={name:"202303/20230309.1 ⭐️ Contribute to open source without code.md"};function h(m,t,f,T,b,C){const l=a("Link");return u(),s("div",null,[t[26]||(t[26]=o("h1",{id:"不编写代码也可以为开源项目做出贡献",tabindex:"-1"},[e("不编写代码也可以为开源项目做出贡献 "),o("a",{class:"header-anchor",href:"#不编写代码也可以为开源项目做出贡献","aria-label":"Permalink to “不编写代码也可以为开源项目做出贡献”"},"​")],-1)),t[27]||(t[27]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202303/16/231703lt3v8fw7t85uya30.jpg",alt:""})],-1)),t[28]||(t[28]=o("blockquote",null,[o("p",null,"如果你想通过非代码贡献成为一个提交者，或者没有时间做代码贡献，那么第一步就是加入社区。")],-1)),t[29]||(t[29]=o("p",null,"对于不同的人来说，开源“社区”意味着不同的东西。我认为开源有点像“爱情”，因为它是关于人和关系的。把开源当作一个社区，因为没有人，就没有源代码，无论是开源还是闭源。",-1)),o("p",null,[t[2]||(t[2]=e("我是 ",-1)),n(l,{href:"https://dolphinscheduler.apache.org/en-us"},{default:p(()=>[...t[0]||(t[0]=[e("Apache DolphinScheduler",-1)])]),_:1}),t[3]||(t[3]=e(" 社区的成员。由于该项目有意保持低代码，因此它吸引了许多 ",-1)),n(l,{href:"https://opensource.com/article/21/2/what-technical"},{default:p(()=>[...t[1]||(t[1]=[e("非软件开发人员",-1)])]),_:1}),t[4]||(t[4]=e("。有时，那些不编写代码的人不确定是否有一种有意义的方式来为主要由源代码组成的开源项目做出贡献。我的经验告诉我，有，我将在本文中解释原因。",-1))]),t[30]||(t[30]=r('<h3 id="向社区做出贡献" tabindex="-1">向社区做出贡献 <a class="header-anchor" href="#向社区做出贡献" aria-label="Permalink to “向社区做出贡献”">​</a></h3><p>在 Apache DolphinScheduler 项目中，我主要负责全球运营、影响力和社区关怀。</p><p>一些人会说项目是树而开源是土壤。这是一个恰当的比喻，它说明了积极培育你想要帮助成长的东西的重要性。</p><p>我有一个更简单的想法：尽一切可能使其变得更好。</p><p>一个社区需要不断的关注，不是因为它很贪心，而是因为它是生活的一部分。社区是你身边的人，无论是物理空间还是在线空间。</p><p>自从加入开源社区以来，我已经独立发起并组织了一些活动，包括：</p><ul><li>平均每月在中国举办一次会议。</li><li>建议社区参与大数据领域内的技术分享。</li><li>协调了中国“大数据”领域几乎所有的开源项目，与这些社区进行了个别访问和交流。</li></ul><p>在我看来，一个优秀的项目应该在一个良好的生态系统中成长。社区需要走出去，交换想法，分享资源，并与其他优秀的社区合作。每个人都应该感受到社区在工作中带来的好处。</p><p>我的海外扩张遵循相同的模式。当然，由于文化和语言的差异，这样做很困难。这需要耗费精力，但这是值得的。</p><p>到目前为止，我们已经在包括美国、印度、新加坡、德国、法国、芬兰等国家成功举办了会议。</p><p>所以我如何为 DolphinScheduler 做出贡献？我是否向项目提交代码？我是社区经理吗？我有正式的职称吗？</p><p>我认为自己是一个助手。我促进沟通和联系，这与任何代码贡献一样，都是 “Apache Way” 的一个例子。</p><h3 id="从-dolphinscheduler-开始" tabindex="-1">从 DolphinScheduler 开始 <a class="header-anchor" href="#从-dolphinscheduler-开始" aria-label="Permalink to “从 DolphinScheduler 开始”">​</a></h3>',13)),o("p",null,[t[6]||(t[6]=e("我第一次接触开源是在开放原子基金会工作时，担任开源教育运营经理。作为中国第一个开源基金会，开放原子运营了以 ",-1)),n(l,{href:"https://gitee.com/openharmony"},{default:p(()=>[...t[5]||(t[5]=[e("OpenHarmony",-1)])]),_:1}),t[7]||(t[7]=e(" 为代表的许多项目。",-1))]),t[31]||(t[31]=o("p",null,"我加入了 DolphinScheduler 社区并发现了一群热衷于分享知识、提供指导和支持，并热衷于帮助其他人发现对他们自己的生活有用的工具的人。",-1)),o("p",null,[t[9]||(t[9]=e("DolphinScheduler 旨在成为一个拥有全球影响力的调度系统，帮助团队以 ",-1)),n(l,{href:"https://opensource.com/article/22/5/practical-tips-agile"},{default:p(()=>[...t[8]||(t[8]=[e("敏捷",-1)])]),_:1}),t[10]||(t[10]=e(" 和高效的方式工作。",-1))]),t[32]||(t[32]=r('<h3 id="对社区的第一印象" tabindex="-1">对社区的第一印象 <a class="header-anchor" href="#对社区的第一印象" aria-label="Permalink to “对社区的第一印象”">​</a></h3><p>听到社区对项目开发的抱怨是一件常见的事情。我们都会时不时地抱怨。也许你报告了一个错误，但开发人员没有解决你的问题。或者，也许你有一个很棒的功能想法，但团队忽略了它。如果你是一个开源社区的成员，你以前就听到过这些不满，如果你没有，你最终会听到。</p><p>我了解到，这些声音对于开源社区来说都很重要。这是一个好现象，因为当你听到这些反馈时，这意味着社区愿意发现错误，报告它们，提出问题和回答问题。听到这些抱怨可能会揭示项目结构中需要改进的地方。社区中是否有志愿者可以回应错误报告并对它们进行分类，以便它们能够被分配给正确的开发人员？是否有一个志愿者组等待成立，以便迅速回应项目论坛或论坛中新人的问题？</p><p>开源项目的门口有一个招待员可以帮助邀请犹豫不决的社区成员。招待员还可以确保没有“门槛”。每个人都受欢迎，每个人都有自己的贡献，即使他们能提供的只是互相帮助的氛围。</p><p>尽管你我都希望能为每个人解决技术问题，但这是不现实的。但任何人都愿意帮助找到解决方案，这是社区的一个伟大优势。这些用户自发地充当了社区的“客户服务”部门。</p><p>在 DolphinScheduler 项目中，我们有很多人（Yan Jiang、Xu Zhiwu、Zhang Qichen、Wang Yuxiang、Xiang Zihao、Yang Qiyu、Yang Jiahao、Gao Chufeng 和 Gao Feng，顺序不分先后！）。即使他们不开发解决方案，他们也不遗余力地寻找能够开发解决方案的人。</p><h3 id="给社区的话" tabindex="-1">给社区的话 <a class="header-anchor" href="#给社区的话" aria-label="Permalink to “给社区的话”">​</a></h3><p>如果你希望通过非代码贡献成为提交者，或者没有时间进行代码贡献，那么第一步就是加入社区。没有注册表格或批准流程，但也没有快速通道。你通过参与加入社区。你通过可靠且持续的参与与其他人建立关系。</p><p>我随时都可以聊天，总是渴望谈论全球活动组织、文档、反馈等。</p><h3 id="成为提交者" tabindex="-1">成为提交者 <a class="header-anchor" href="#成为提交者" aria-label="Permalink to “成为提交者”">​</a></h3><p>Apache DolphinScheduler 面临着许多挑战。大多数公司，即使是支持开源的公司，也会选择非开源的商业工具。我希望与社区合作伙伴一起，使 DolphinScheduler 成为世界级的调度系统。我希望每个人都可以收获他们想要的技术成果，而 DolphinScheduler 可以帮助他们实现这一目标。</p><p>加入我们的社区，帮助我们推广开放和敏捷的工作方式。或者找到一个需要你非编码技能的项目。发现让你的同龄人社区获得力量是多么酷和有趣！</p><hr>',13)),o("p",null,[t[12]||(t[12]=e("via: ",-1)),n(l,{href:"https://opensource.com/article/23/3/non-code-contribution-open-source"},{default:p(()=>[...t[11]||(t[11]=[e("https://opensource.com/article/23/3/non-code-contribution-open-source",-1)])]),_:1})]),o("p",null,[t[17]||(t[17]=e("作者：",-1)),n(l,{href:"https://opensource.com/users/debra-chen"},{default:p(()=>[...t[13]||(t[13]=[e("Debra Chen",-1)])]),_:1}),t[18]||(t[18]=e(" 选题：",-1)),n(l,{href:"https://github.com/lkxed/"},{default:p(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),n(l,{href:"https://github.com/Cubik65536"},{default:p(()=>[...t[15]||(t[15]=[e("Cubik65536",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),n(l,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:p(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const S